@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  * {
    -webkit-tap-highlight-color: transparent;
  }

  html {
    @apply antialiased;
    font-feature-settings: "ss01", "ss02", "cv01";
  }

  body {
    @apply bg-finn-bg text-finn-text;
    overflow-x: hidden;
  }

  /* Hide scrollbar but keep functionality */
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

@layer components {
  .finn-card {
    @apply bg-finn-card border border-finn-border rounded-xl p-3;
  }

  .finn-badge {
    @apply inline-flex items-center px-1.5 py-0.5 rounded text-2xs font-medium uppercase tracking-wider;
  }

  .finn-badge-red {
    @apply finn-badge bg-red-500/15 text-red-400;
  }

  .finn-badge-green {
    @apply finn-badge bg-green-500/15 text-green-400;
  }

  .finn-badge-amber {
    @apply finn-badge bg-amber-500/15 text-amber-400;
  }

  .finn-badge-blue {
    @apply finn-badge bg-blue-500/15 text-blue-400;
  }

  .finn-badge-muted {
    @apply finn-badge bg-finn-border text-finn-muted;
  }

  .finn-section-title {
    @apply text-xs font-semibold uppercase tracking-wider text-finn-muted mb-2;
  }

  /* Shimmer loading animation */
  .finn-shimmer {
    @apply animate-pulse bg-finn-border rounded;
  }
}

@layer utilities {
  .text-positive {
    @apply text-finn-green;
  }
  .text-negative {
    @apply text-finn-red;
  }
  .text-warning {
    @apply text-finn-amber;
  }
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Format a number in Indian notation (lakhs/crores).
 * e.g., 240000 → "₹2.4L Cr", 19800 → "₹19,800 Cr"
 */
export function formatIndianCurrency(crores: number): string {
  if (crores >= 100000) {
    return `₹${(crores / 100000).toFixed(1)}L Cr`;
  }
  if (crores >= 1000) {
    return `₹${(crores / 1000).toFixed(1)}K Cr`;
  }
  return `₹${crores.toLocaleString("en-IN")} Cr`;
}

/**
 * Format a percentage change with + or - prefix and color class.
 */
export function formatChange(pct: number | null | undefined): {
  text: string;
  className: string;
} {
  if (pct == null) return { text: "—", className: "text-finn-muted" };
  const sign = pct >= 0 ? "+" : "";
  return {
    text: `${sign}${pct.toFixed(1)}%`,
    className: pct >= 0 ? "text-positive" : "text-negative",
  };
}

/**
 * Format a ticker symbol for display.
 * "RELIANCE.NS" → "RELIANCE"
 */
export function displayTicker(ticker: string): string {
  return ticker.replace(/\.(NS|BO)$/, "");
}

/**
 * Relative time display.
 * e.g., "2h ago", "yesterday", "3d ago"
 */
export function timeAgo(dateStr: string): string {
  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffMins < 1) return "just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays === 1) return "yesterday";
  if (diffDays < 7) return `${diffDays}d ago`;
  return date.toLocaleDateString("en-IN", { day: "numeric", month: "short" });
}

/**
 * Priority label and color.
 */
export function priorityMeta(priority: number): {
  label: string;
  color: string;
  dot: string;
} {
  switch (priority) {
    case 1:
      return { label: "Material", color: "finn-badge-red", dot: "bg-red-400" };
    case 2:
      return {
        label: "Notable",
        color: "finn-badge-amber",
        dot: "bg-amber-400",
      };
    default:
      return {
        label: "Routine",
        color: "finn-badge-muted",
        dot: "bg-finn-muted",
      };
  }
}

/* ─── Shared TypeScript types for FINN ─── */

export interface Stock {
  ticker: string;
  name: string;
  sector: string;
  in_portfolio: boolean;
}

export interface PriceData {
  ticker: string;
  name: string;
  sector: string;
  fetched_at: string;
  current: {
    price: number;
    change_pct: number;
    volume: number;
    vol_ratio: number | null;
    market_cap: number;
    name: string;
    sector: string;
    industry: string;
  };
  history: PricePoint[];
}

export interface PricePoint {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  change_pct: number;
  vol_ratio: number | null;
}

export interface Announcement {
  id: string;
  ticker: string;
  company_name: string;
  timestamp: string;
  headline: string;
  category: AnnouncementCategory;
  priority: 1 | 2 | 3;
  summary: string;
  source_url: string;
  raw_text: string;
  enrichment: ResultsEnrichment | ManagementEnrichment | Record<string, never>;
  model_used: string | null;
  tokens: { in: number; out: number };
}

export type AnnouncementCategory =
  | "results"
  | "M&A"
  | "fund_raise"
  | "management_change"
  | "litigation"
  | "insider_trading"
  | "earnings_call"
  | "investor_meetings"
  | "credit_rating"
  | "dividend"
  | "bonus_split"
  | "capex"
  | "press_release"
  | "postal_ballot"
  | "agm_egm"
  | "pledging"
  | "unclassified";

export interface ResultsEnrichment {
  quarter?: string;
  revenue?: MetricWithChange;
  ebitda?: MetricWithChange;
  pbt?: MetricWithChange;
  pat?: MetricWithChange;
  highlights?: string;
}

export interface MetricWithChange {
  value: number;
  qoq: number | null;
  yoy: number | null;
}

export interface ManagementEnrichment {
  person_name?: string;
  role?: string;
  action?: "joined" | "resigned" | "retired";
  background?: string;
}

export interface Alert {
  ticker: string;
  type: "volume_spike" | "price_move";
  value: number;
  threshold: number;
  message: string;
  date: string;
  close: number;
}

export interface NarrativeVsNumbers {
  summary: string;
  quarters: QuarterAnalysis[];
  credibility_score: "high" | "medium" | "low";
  pattern: string;
}

export interface QuarterAnalysis {
  quarter: string;
  guided: GuidanceItem[];
  delivered: DeliveredItem[];
  verdict: "hit" | "miss" | "beat";
  commentary: string;
}

export interface GuidanceItem {
  metric: string;
  guidance: string;
  source: string;
}

export interface DeliveredItem {
  metric: string;
  actual: string;
  source: string;
}

export interface ResearchData {
  ticker: string;
  generated_at: string;
  source_documents: SourceDocument[];
  narrative_vs_numbers: NarrativeVsNumbers;
  financial_snapshot?: Record<string, unknown>;
  cash_quality?: Record<string, unknown>;
  bull_bear?: { bull: string; bear: string };
  model_used: string;
  tokens: { in: number; out: number };
  cost_estimate_usd: number;
}

export interface SourceDocument {
  type: "annual_report" | "concall_transcript" | "results_filing";
  year?: string;
  quarter?: string;
  url: string;
  pages?: number;
}

export interface DigestData {
  generated_at: string;
  window: string;
  material: Announcement[];
  notable: Announcement[];
  routine: Announcement[];
  alerts: Alert[];
  portfolio_summary: PortfolioTicker[];
}

export interface PortfolioTicker {
  ticker: string;
  name: string;
  price: number;
  change_pct: number;
  has_announcement: boolean;
}

export interface AlertConfig {
  volume_threshold: number;
  price_move_pct: number;
  watched_categories: AnnouncementCategory[];
}

