97: /** Assemble the briefing from real pipeline outputs only. */
98: export function getDigest(windowHours = 24): DigestData {
99:   const portfolio = getPortfolio();
100:   const cfg: AlertConfig = portfolio?.alert_config ?? {
101:     volume_threshold: 2,
102:     price_move_pct: 3,
103:     watched_categories: [],
104:   };
105:   const held = (portfolio?.stocks ?? []).filter((s) => s.in_portfolio);
106: 
107:   const summary: PortfolioTicker[] = [];
108:   const alerts: Alert[] = [];
109:   const announcements: Announcement[] = [];
110:   const missingPrices: string[] = [];
111:   let pricesAsOf: string | null = null;
112: 
113:   const cutoff = Date.now() - windowHours * 3600 * 1000;
114: 
115:   for (const s of held) {
116:     const p = getPrices(s.ticker);
117:     const anns = getAnnouncements(s.ticker).filter((a) => {
118:       const t = Date.parse(a.timestamp);
119:       return Number.isNaN(t) || t >= cutoff;
120:     });
121:     announcements.push(...anns);
122: 
123:     if (!p || !p.history.length) {
124:       missingPrices.push(s.ticker);
125:       continue;
126:     }
127:     const latest = p.history.at(-1)!;
128:     if (!pricesAsOf || latest.date > pricesAsOf) pricesAsOf = latest.date;
129:     summary.push({
130:       ticker: s.ticker,
131:       name: s.name,
132:       price: latest.close,
133:       change_pct: latest.change_pct,
134:       has_announcement: anns.length > 0,
135:     });
136:     alerts.push(...computeAlerts(p, cfg));
137:   }
138: 
139:   announcements.sort((a, b) => a.priority - b.priority || b.timestamp.localeCompare(a.timestamp));
140: 
141:   return {
142:     generated_at: new Date().toISOString(),
143:     window: `${windowHours}h`,
144:     prices_as_of: pricesAsOf,
145:     missing_prices: missingPrices,
146:     announcements_ingested: announcements.length > 0,
147:     material: announcements.filter((a) => a.priority === 1),
148:     notable: announcements.filter((a) => a.priority === 2),
149:     routine: announcements.filter((a) => a.priority === 3),
150:     alerts,
151:     portfolio_summary: summary,
152:   };
153: }

