3: import { useState } from "react";
4: import { Search, X } from "lucide-react";
5: import { cn, displayTicker } from "@/lib/utils";
6: import type { ResearchData } from "@/lib/types";
7: import { ResearchPanel } from "@/components/research/research-panel";
8: 
9: // Quick-pick list only. Research availability is decided by the API (404 = not
10: // generated yet); nothing here claims research exists.
11: const SUGGESTIONS = [
12:   { ticker: "INFY.NS", label: "Infosys · 5 transcripts + 5 results filings" },
13:   { ticker: "RELIANCE.NS", label: "Reliance Industries · 5 transcripts + 5 results filings" },
14:   { ticker: "TCS.NS", label: "TCS · 5 transcripts + 5 results filings" },
15:   { ticker: "ICICIBANK.NS", label: "ICICI Bank · 5 transcripts + 5 results filings" },
16:   { ticker: "ETERNAL.NS", label: "Eternal (formerly Zomato) · 5 transcripts + 5 results filings" },
17:   { ticker: "HDFCBANK.NS", label: "HDFC Bank" },
18:   { ticker: "BAJFINANCE.NS", label: "Bajaj Finance" },
19:   { ticker: "ITC.NS", label: "ITC" },
20: ];
21: 
22: export function CommandBar() {
23:   const [isOpen, setIsOpen] = useState(false);
24:   const [query, setQuery] = useState("");
25:   const [loading, setLoading] = useState(false);
26:   const [research, setResearch] = useState<ResearchData | null>(null);
27:   const [error, setError] = useState<string | null>(null);
28: 
29:   const filtered = query
30:     ? SUGGESTIONS.filter(
31:         (s) =>
32:           s.label.toLowerCase().includes(query.toLowerCase()) ||
33:           displayTicker(s.ticker).toLowerCase().includes(query.toLowerCase())
34:       )
35:     : SUGGESTIONS;
36: 
37:   async function handleSearch(ticker: string) {
38:     setLoading(true);
39:     setError(null);
40:     try {
41:       const symbol = ticker.replace(/\.(NS|BO)$/, "");
42:       const res = await fetch(`/api/research/${symbol}`);
43:       if (!res.ok) {
44:         if (res.status === 404) {
45:           throw new Error(
46:             `No research generated for ${symbol} yet. Research is only shown once it has been built from fetched annual reports and concall transcripts.`
47:           );
48:         }
49:         throw new Error("Research request failed");
50:       }
51:       const data = await res.json();
52:       setResearch(data);
53:       setIsOpen(false);
54:       setQuery("");
55:     } catch (e: unknown) {
56:       setError(e instanceof Error ? e.message : "Failed to load research");
57:     } finally {
58:       setLoading(false);
59:     }
60:   }
61: 
62:   if (research) {
63:     return (
64:       <ResearchPanel
65:         data={research}
66:         onClose={() => setResearch(null)}
67:       />
68:     );
69:   }
70: 
71:   return (
72:     <>
73:       {/* Floating command bar trigger */}
74:       <div className="fixed bottom-0 left-0 right-0 max-w-[430px] mx-auto p-3 z-40">
75:         <button
76:           onClick={() => setIsOpen(true)}
77:           className={cn(
78:             "w-full flex items-center gap-2 px-4 py-3 rounded-xl",
79:             "bg-finn-card border border-finn-border",
80:             "text-finn-muted text-sm",
81:             "shadow-lg shadow-black/40",
82:             "active:scale-[0.98] transition-transform"
83:           )}
84:         >
85:           <Search className="w-4 h-4" />
86:           <span>Research any company...</span>
87:         </button>
88:       </div>
89: 
90:       {/* Full-screen search panel */}
91:       {isOpen && (
92:         <div className="fixed inset-0 z-50 bg-finn-bg flex flex-col max-w-[430px] mx-auto">
93:           {/* Search input */}
94:           <div className="flex items-center gap-2 px-4 py-3 border-b border-finn-border">
95:             <Search className="w-4 h-4 text-finn-muted flex-shrink-0" />
96:             <input
97:               type="text"
98:               value={query}
99:               onChange={(e) => setQuery(e.target.value)}
100:               placeholder="Search ticker or company name..."
101:               className="flex-1 bg-transparent text-sm text-finn-text placeholder:text-finn-muted outline-none"
102:               autoFocus
103:               onKeyDown={(e) => {
104:                 if (e.key === "Enter" && filtered.length > 0) {
105:                   handleSearch(filtered[0].ticker);
106:                 }
107:               }}
108:             />
109:             <button
110:               onClick={() => {
111:                 setIsOpen(false);
112:                 setQuery("");
113:                 setError(null);
114:               }}
115:               className="w-6 h-6 rounded-full bg-finn-surface flex items-center justify-center"
116:             >
117:               <X className="w-3.5 h-3.5 text-finn-muted" />
118:             </button>
119:           </div>
120: 
121:           {/* Error */}
122:           {error && (
123:             <div className="mx-4 mt-3 px-3 py-2 rounded-lg bg-red-500/10 border border-red-500/20 text-xs text-red-400">
124:               {error}
125:             </div>
126:           )}
127: 
128:           {/* Loading */}
129:           {loading && (
130:             <div className="flex items-center justify-center py-12">
131:               <div className="w-6 h-6 border-2 border-finn-accent border-t-transparent rounded-full animate-spin" />
132:               <span className="ml-2 text-sm text-finn-muted">
133:                 Analyzing...
134:               </span>
135:             </div>
136:           )}
137: 
138:           {/* Suggestions */}
139:           {!loading && (
140:             <div className="flex-1 overflow-y-auto p-4">
141:               <div className="finn-section-title">
142:                 {query ? "Results" : "Quick research"}
143:               </div>
144:               <div className="space-y-1">
145:                 {filtered.map((s) => (
146:                   <button
147:                     key={s.ticker}
148:                     onClick={() => handleSearch(s.ticker)}
149:                     className={cn(
150:                       "w-full flex items-center justify-between px-3 py-2.5 rounded-lg",
151:                       "hover:bg-finn-surface active:bg-finn-card transition-colors",
152:                       "text-left"
153:                     )}
154:                   >
155:                     <div>
156:                       <span className="text-sm font-medium">
157:                         {displayTicker(s.ticker)}
158:                       </span>
159:                       <span className="text-xs text-finn-muted ml-2">
160:                         {s.label}
161:                       </span>
162:                     </div>
163:                     <Search className="w-3.5 h-3.5 text-finn-muted" />
164:                   </button>
165:                 ))}
166:               </div>
167:               {filtered.length === 0 && (
168:                 <p className="text-sm text-finn-muted text-center py-8">
169:                   No matching companies. Try the NSE ticker symbol.
170:                 </p>
171:               )}
172:             </div>
173:           )}
174:         </div>
175:       )}
176:     </>
177:   );
178: }

