61: function computeAlerts(prices: PriceData, cfg: AlertConfig): Alert[] {
62:   const latest = prices.history.at(-1);
63:   if (!latest) return [];
64:   const out: Alert[] = [];
65:   const base = { ticker: prices.ticker, date: latest.date, close: latest.close };
66: 
67:   if (latest.vol_guard) {
68:     out.push({
69:       ...base,
70:       type: "volume_unreliable",
71:       value: latest.vol_ratio ?? 0,
72:       threshold: cfg.volume_threshold,
73:       message: `Volume check paused: ${latest.vol_guard}`,
74:     });
75:   } else if (latest.vol_ratio != null && latest.vol_ratio >= cfg.volume_threshold) {
76:     out.push({
77:       ...base,
78:       type: "volume_spike",
79:       value: latest.vol_ratio,
80:       threshold: cfg.volume_threshold,
81:       message: `Volume ${latest.vol_ratio}× the prior 20-day average`,
82:     });
83:   }
84: 
85:   if (Math.abs(latest.change_pct) >= cfg.price_move_pct) {
86:     out.push({
87:       ...base,
88:       type: "price_move",
89:       value: latest.change_pct,
90:       threshold: cfg.price_move_pct,
91:       message: `Price ${latest.change_pct > 0 ? "up" : "down"} ${Math.abs(latest.change_pct).toFixed(1)}% on the day`,
92:     });
93:   }
94:   return out;
95: }
