98: export function getDigest(windowHours = 24): DigestData {
99:   const portfolio = getPortfolio();
100:   const cfg: AlertConfig = portfolio?.alert_config ?? {
101:     volume_threshold: 2,
102:     price_move_pct: 3,
103:     watched_categories: [],
104:   };
105:   const held = (portfolio?.stocks ?? []).filter((s) => s.in_portfolio);
106: 
107:   const summary: PortfolioTicker[] = [];
108:   const alerts: Alert[] = [];
109:   const announcements: Announcement[] = [];
110:   const missingPrices: string[] = [];
111:   let pricesAsOf: string | null = null;
112:   let totalOnDisk = 0;
113: 
114:   const cutoff = Date.now() - windowHours * 3600 * 1000;
115: 
116:   for (const s of held) {
117:     const p = getPrices(s.ticker);
118:     const allTickerAnns = getAnnouncements(s.ticker);
119:     totalOnDisk += allTickerAnns.length;
120:     const anns = allTickerAnns.filter((a) => {
121:       const t = Date.parse(a.timestamp);
122:       return Number.isNaN(t) || t >= cutoff;
123:     });
124:     announcements.push(...anns);
125: 
126:     if (!p || !p.history.length) {
127:       missingPrices.push(s.ticker);
128:       continue;
129:     }
130:     const latest = p.history.at(-1)!;
131:     if (!pricesAsOf || latest.date > pricesAsOf) pricesAsOf = latest.date;
132:     summary.push({
133:       ticker: s.ticker,
134:       name: s.name,
135:       price: latest.close,
136:       change_pct: latest.change_pct,
137:       has_announcement: anns.length > 0,
138:     });
139:     alerts.push(...computeAlerts(p, cfg));
140:   }
141: 
142:   announcements.sort((a, b) => a.priority - b.priority || b.timestamp.localeCompare(a.timestamp));
143: 
144:   const windowLabel =
145:     windowHours >= 24 && windowHours % 24 === 0
146:       ? `${windowHours / 24}d`
147:       : `${windowHours}h`;
148: 
149:   return {
150:     generated_at: new Date().toISOString(),
151:     window: windowLabel,
152:     prices_as_of: pricesAsOf,
153:     missing_prices: missingPrices,
154:     announcements_ingested: totalOnDisk > 0,
155:     material: announcements.filter((a) => a.priority === 1),
156:     notable: announcements.filter((a) => a.priority === 2),
157:     routine: announcements.filter((a) => a.priority === 3),
158:     alerts,
159:     portfolio_summary: summary,
160:   };
161: }

