    setSelectedHours(hours);
    await refetch(hours, alertConfig);
  }

  async function handleSaveSettings(cfg: AlertConfig) {
    setAlertConfig(cfg);
    setShowSettings(false);
    await refetch(selectedHours, cfg);
  }

