cd finn && python3 -c "
import subprocess, re

# Scan git log -p
log = subprocess.check_output(['git', 'log', '-p'], text=True)

patterns = {
    'Gemini API Key': r'AIza[0-9A-Za-z\-_]{35}',
    'GitHub Token': r'ghp_[0-9A-Za-z]{36}',
    'Generic Private Key': r'-----BEGIN (?:RSA )?PRIVATE KEY-----',
    'Vercel Token': r'vercel_[0-9A-Za-z\-_]{20,}',
    'Hardcoded GEMINI_API_KEY value': r'GEMINI_API_KEY\s*=\s*[\"|\'][A-Za-z0-9_\-]{20,}[\"|\']',
}

findings = []
for name, pat in patterns.items():
    matches = re.findall(pat, log)
    if matches:
        findings.append(f'{name}: {len(matches)} matches found!')

print('=== GIT HISTORY SECRETS SCAN ===')
if not findings:
    print('PASS: Zero secrets found in entire git history across all commits.')
else:
    for f in findings:
        print('FAIL:', f)

# Check tracked files
status = subprocess.check_output(['git', 'status', '--ignored'], text=True)
print('\n=== .env TRACKING CHECK ===')
if '.env' in status and 'Ignored files:' in status:
    print('PASS: .env is in .gitignore and untracked.')
else:
    print('FAIL: .env is tracked or not in .gitignore!')
"
